import logging

import attr
from typing import Optional
from taf.config.testline.appserver import TafUeAppServer


@attr.s(cmp=False)
class TafUeDataTransferProtocol(object):
    """
    More information about TafUeDataTransferProtocol model can be found at the following links:
    __init__.py: https://confluence.ext.net.nokia.com/display/AbstractLibs/taf.ue%3A+__init__.py+configuration+file
    yaml: https://confluence.ext.net.nokia.com/display/AbstractLibs/ute_ue%3A+YAML+configuration+file

    :param str protocol_name: MANDATORY protocol name, e.g.: iperf, ping etc.
    :param TafUeAppServer app_server: MANDATORY app server definition
    :param Optional[int] interval: OPTIONAL interval value
    :param Optional[str] binary_path: OPTIONAL binary path
    :param Optional[str] interface_name: OPTIONAL interface name
    :param Optional[int] server_close_delay: OPTIONAL delay in closing iperf server
                                                in case of delay between client ans server hosts
    :param Optional[str] bind_ue_ip: OPTIONAL parameter to trigger or not binding to ue ip in uplink data transfer
                                        - True - used by default.
                                        - False - to not use binding.
    :param Optional[int] version: OPTIONAL to determine usage of iperf3 in tests,
                                    allowed values: 3 or 2 (set by default)
    :param Optional[bool] dt_from_uepc: OPTIONAL parameter to define if data transfer should be run directly from UE or
                                        from UEPC
                                        - False - used by default - dt transfer is run directly from UE.
                                        - True - dt transfer is run from UE PC.
    """

    protocol_name = attr.ib(type=str)
    app_server = attr.ib(type=TafUeAppServer)
    interval = attr.ib(type=Optional[int], default=1)
    binary_path = attr.ib(type=Optional[str], default=None)
    interface_name = attr.ib(type=Optional[str], default=None)
    server_close_delay = attr.ib(type=Optional[int], default=50)
    bind_ue_ip = attr.ib(type=Optional[str], default=None)
    version = attr.ib(type=Optional[int], default=None)
    dt_from_uepc = attr.ib(type=Optional[bool], default=False)


@attr.s(cmp=False)
class TafUeAtDataTransferProtocol(TafUeDataTransferProtocol):
    """
    Deprecated, use TafUeDataTransferProtocol class instead.
    """
    def __attrs_post_init__(self):
        logger = logging.getLogger(__name__)
        logger.warning("TafUeAtDataTransferProtocol is deprecated and will be removed at the end of 09.2023, "
                       "use TafUeDataTransferProtocol class instead")
